/**
 * Intercom relay pass — Cloudflare Worker
 *
 * Hands the Intercom web app short-lived TURN (relay) credentials,
 * and refuses once this month's relay usage reaches your cap.
 * Also transcribes Talkback clips (POST /stt) with Whisper on Workers AI,
 * stopping at a daily cap so it stays inside the free allowance.
 *
 * Settings → Variables and Secrets:
 *   Secret  TURN_KEY_ID         TURN key ID          (Realtime → TURN)
 *   Secret  TURN_KEY_API_TOKEN  TURN key API token   (shown once when you create the key)
 *   Secret  CF_ACCOUNT_ID       your Cloudflare account ID
 *   Secret  CF_ANALYTICS_TOKEN  API token with "Account Analytics: Read"
 *   Text    ALLOWED_ORIGINS     e.g. https://intercom.asahina.me,https://yourname.github.io
 *   Text    MONTHLY_CAP_GB      e.g. 900
 *   Text    STT_DAILY_MIN       daily transcription cap in minutes (default 200 ≈ the free 10,000 neurons)
 *
 * Settings → Bindings → Add → Workers AI, variable name: AI   (needed for transcription)
 *
 * Share links: /r/1234 is the room link people get from Share / Copy link. Link previews (iMessage etc.)
 * get a page with a picture of the room code (/og/1234.png); everyone else goes straight to the app.
 *   Text    APP_URL             optional, default https://ifb.asahina.me/
 */

const PASS_TTL = 6 * 3600;          // each relay pass lasts 6 hours
const PER_IP_PER_HOUR = 120;        // soft limit per network (phones now reuse a pass for hours, so this is plenty)
const USAGE_CACHE_SEC = 600;        // re-check usage at most every 10 minutes
const STUN_ONLY = [{ urls: ['stun:stun.cloudflare.com:3478'] }];

export default {
  async fetch(req, env, ctx) {
    const sm = new URL(req.url).pathname.match(/^\/(r|og)\/(\d{4})(?:\.png)?\/?$/);   // share links: open to everyone
    if (sm) return shareLink(sm[1], sm[2], req, env, ctx);
    const origin = req.headers.get('Origin') || '';
    const allowed = (env.ALLOWED_ORIGINS || '').split(',').map(s => s.trim()).filter(Boolean);
    const okOrigin = allowed.includes(origin);
    const cors = {
      'Access-Control-Allow-Origin': okOrigin ? origin : 'null',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, X-Clip-Seconds',
      'Access-Control-Max-Age': '86400',
      'Vary': 'Origin',
      'Cache-Control': 'no-store',
      'Content-Type': 'application/json',
    };
    const reply = (body, status = 200) => new Response(JSON.stringify({ ...body, share: true }), { status, headers: cors });

    if (req.method === 'OPTIONS') return new Response(null, { status: okOrigin ? 204 : 403, headers: cors });
    if (!okOrigin) return reply({ error: 'origin not allowed' }, 403);

    const url = new URL(req.url);
    if (url.pathname === '/stt') return transcribe(req, env, ctx, reply);
    if (url.pathname === '/usage') {                      // quick check from a browser on your site
      const u = await monthUsage(env, ctx);
      return reply({ usedGB: u.gb, capGB: cap(env), stale: u.stale, ok: u.gb !== null && u.gb < cap(env) });
    }

    // Soft per-IP rate limit (per Cloudflare location — good enough to stop casual abuse)
    const ip = req.headers.get('CF-Connecting-IP') || 'unknown';
    if (await overRate(ip)) return reply({ iceServers: STUN_ONLY, relay: false, reason: 'rate limited' });

    // Hard monthly cap
    const u = await monthUsage(env, ctx);
    if (u.gb === null) return reply({ iceServers: STUN_ONLY, relay: false, reason: 'usage unknown' });
    if (u.gb >= cap(env)) return reply({ iceServers: STUN_ONLY, relay: false, reason: 'monthly cap reached', usedGB: u.gb });

    // Mint a short-lived relay pass
    const r = await fetch(`https://rtc.live.cloudflare.com/v1/turn/keys/${env.TURN_KEY_ID}/credentials/generate-ice-servers`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${env.TURN_KEY_API_TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ ttl: PASS_TTL }),
    });
    if (!r.ok) return reply({ iceServers: STUN_ONLY, relay: false, reason: `turn api ${r.status}` });
    const data = await r.json();
    // Browsers block port 53 — drop those addresses
    const iceServers = (data.iceServers || []).map(s => {
      const urls = (Array.isArray(s.urls) ? s.urls : [s.urls]).filter(u => !/:53(\?|$)/.test(u));
      return { ...s, urls };
    }).filter(s => s.urls.length);
    return reply({ iceServers, relay: true, ttl: PASS_TTL, usedGB: u.gb, capGB: cap(env) });
  },
};

const cap = env => Number(env.MONTHLY_CAP_GB) || 900;

async function overRate(ip, limit = PER_IP_PER_HOUR) {
  const hour = Math.floor(Date.now() / 3600e3);
  const key = new Request(`https://rate.local/${encodeURIComponent(ip)}/${hour}`);
  const cache = caches.default;
  const hit = await cache.match(key);
  const n = hit ? Number(await hit.text()) + 1 : 1;
  await cache.put(key, new Response(String(n), { headers: { 'Cache-Control': 'max-age=3600' } }));
  return n > limit;
}

// This month's TURN traffic (in + out) in GB. Cached for 10 min; falls back to the last
// good value (up to a day old) if the analytics API hiccups; null if never known.
async function monthUsage(env, ctx) {
  const cache = caches.default;
  const fresh = new Request('https://usage.local/fresh');
  const backup = new Request('https://usage.local/backup');
  const hit = await cache.match(fresh);
  if (hit) return { gb: Number(await hit.text()), stale: false };

  try {
    const now = new Date();
    const from = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)).toISOString().slice(0, 10);
    const to = now.toISOString().slice(0, 10);
    const query = `query ($acct: String!, $from: Date!, $to: Date!) {
      viewer { accounts(filter: { accountTag: $acct }) {
        callsTurnUsageAdaptiveGroups(limit: 10000, filter: { date_geq: $from, date_leq: $to }) {
          sum { egressBytes ingressBytes }
        } } } }`;
    const r = await fetch('https://api.cloudflare.com/client/v4/graphql', {
      method: 'POST',
      headers: { Authorization: `Bearer ${env.CF_ANALYTICS_TOKEN}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ query, variables: { acct: env.CF_ACCOUNT_ID, from, to } }),
    });
    const j = await r.json();
    if (!r.ok || j.errors?.length) throw new Error(JSON.stringify(j.errors || r.status));
    const groups = j.data?.viewer?.accounts?.[0]?.callsTurnUsageAdaptiveGroups || [];
    const bytes = groups.reduce((t, g) => t + (g.sum?.egressBytes || 0) + (g.sum?.ingressBytes || 0), 0);
    const gb = bytes / 1e9;
    const save = (k, s) => cache.put(k, new Response(String(gb), { headers: { 'Cache-Control': `max-age=${s}` } }));
    ctx.waitUntil(Promise.all([save(fresh, USAGE_CACHE_SEC), save(backup, 86400)]));
    return { gb, stale: false };
  } catch (e) {
    const old = await cache.match(backup);
    return old ? { gb: Number(await old.text()), stale: true } : { gb: null, stale: true, error: String(e) };
  }
}

/* ---------- Talkback transcription ----------
   Body: a short WAV clip (16 kHz mono). Reply: { text } or { error: 'limit', resetsAt }.
   Counts audio seconds per UTC day and stops at STT_DAILY_MIN, so it never runs past the
   free daily allowance (on a free Workers plan Cloudflare would also refuse past it). */
const STT_MODEL = '@cf/openai/whisper-large-v3-turbo';
const STT_PER_IP_PER_HOUR = 1500;
async function transcribe(req, env, ctx, reply){
  if (req.method !== 'POST') return reply({ error: 'POST a WAV clip' }, 405);
  if (!env.AI) return reply({ error: 'setup', reason: 'Add a Workers AI binding named AI' }, 500);
  const day = new Date().toISOString().slice(0, 10);
  const resetsAt = Date.parse(day + 'T00:00:00Z') + 86400e3;
  const capSec = (Number(env.STT_DAILY_MIN) || 200) * 60;
  const ip = req.headers.get('CF-Connecting-IP') || 'unknown';
  if (await overRate('stt-' + ip, STT_PER_IP_PER_HOUR)) return reply({ error: 'busy' }, 429);

  const buf = await req.arrayBuffer();
  if (buf.byteLength < 1000 || buf.byteLength > 2_000_000) return reply({ error: 'bad clip' }, 400);
  const secs = Math.max(0.5, Math.min(60, Number(req.headers.get('X-Clip-Seconds')) || (buf.byteLength - 44) / 32000));

  const cache = caches.default, key = new Request(`https://stt.local/${day}`);
  const hit = await cache.match(key);
  const used = hit ? Number(await hit.text()) : 0;
  if (used + secs > capSec) return reply({ error: 'limit', resetsAt, usedMin: Math.round(used / 60) });

  let out;
  try {
    out = await env.AI.run(STT_MODEL, { audio: toB64(new Uint8Array(buf)), language: 'en', vad_filter: true });
  } catch (e) {
    const msg = String(e?.message || e);
    if (/4006|allocation|neurons/i.test(msg)) {          // Cloudflare's own daily free limit
      ctx.waitUntil(cache.put(key, new Response(String(capSec), { headers: { 'Cache-Control': 'max-age=86400' } })));
      return reply({ error: 'limit', resetsAt });
    }
    return reply({ error: 'stt failed' }, 502);
  }
  ctx.waitUntil(cache.put(key, new Response(String(used + secs), { headers: { 'Cache-Control': 'max-age=86400' } })));
  return reply({ text: (out?.text || '').trim(), usedMin: Math.round((used + secs) / 60), capMin: capSec / 60 });
}
function toB64(u8){
  let s = '';
  for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));
  return btoa(s);
}

/* ---------- Share links with a rich preview ----------
   /r/1234      people → redirect to the app with ?code=1234; link-preview bots → a page with title + picture
   /og/1234.png the preview picture (800×420): a fixed background with the 4 digits drawn in, cached for a week */
const BOT_UA = /facebookexternalhit|facebot|twitterbot|slackbot|discordbot|whatsapp|telegrambot|linkedinbot|skypeuripreview|embedly|pinterest|redditbot|applebot|googlebot|bingbot|iframely|preview/i;
async function shareLink(kind, code, req, env, ctx){
  const app = (env.APP_URL || 'https://ifb.asahina.me/') + '?code=' + code;
  if (kind === 'og') return ogImage(code, req, ctx);
  const ua = req.headers.get('User-Agent') || '';
  if (!BOT_UA.test(ua)) return Response.redirect(app, 302);
  const self = new URL(req.url).origin, title = `Join room ${code} · Intercom`;
  const html = `<!doctype html><html><head><meta charset="utf-8">
<title>${title}</title>
<meta property="og:title" content="${title}">
<meta property="og:site_name" content="Intercom">
<meta property="og:type" content="website">
<meta property="og:url" content="${self}/r/${code}">
<meta property="og:image" content="${self}/og/${code}.png">
<meta property="og:image:type" content="image/png">
<meta property="og:image:width" content="${OG.meta.W}"><meta property="og:image:height" content="${OG.meta.H}">
<meta property="og:image:alt" content="Intercom room ${code}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${title}">
<meta name="twitter:image" content="${self}/og/${code}.png">
</head><body><a href="${app}">${title}</a></body></html>`;
  return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=3600' } });
}

async function ogImage(code, req, ctx){
  const cache = caches.default, key = new Request(new URL(req.url).origin + '/og/' + code + '.png');
  const hit = await cache.match(key);
  if (hit) return hit;
  const png = await renderOg(code);
  const res = new Response(png, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=604800, immutable' } });
  ctx.waitUntil(cache.put(key, res.clone()));
  return res;
}

const b64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
async function zlibIn(u8){ return new Uint8Array(await new Response(new Blob([u8]).stream().pipeThrough(new DecompressionStream('deflate'))).arrayBuffer()); }
let OG_CACHE = null;                                   // decoded pieces, kept between requests
async function ogParts(){
  if (!OG_CACHE) OG_CACHE = { base: await zlibIn(b64(OG.base)), masks: await zlibIn(b64(OG.masks)), lut: b64(OG.lut), pal: b64(OG.pal), top: b64(OG.top) };
  return OG_CACHE;
}
/* Fast path, so a new code costs ~1 ms of CPU: everything above the digits never changes, so it's stored
   already compressed (OG.top). Only the rows from the digits down are filled in here and added uncompressed. */
async function renderOg(code){
  const { W, H, y0, y1, slots } = OG.meta, P = await ogParts();
  const rows = H - y0, px = P.base.slice();            // palette indexes for rows y0..H
  const mh = y1 - y0;
  let off = 0;
  slots.forEach(([x0, x1], i) => {
    const mw = x1 - x0, m = off + (+code[i]) * mw * mh;
    for (let y = 0; y < mh; y++) for (let x = 0; x < mw; x++) {
      const a = P.masks[m + y * mw + x];
      if (a) { const k = y * W + x0 + x; px[k] = P.lut[px[k] * 16 + a]; }
    }
    off += 10 * mw * mh;
  });
  const raw = new Uint8Array((W + 1) * rows);          // each row: filter byte 0 + pixels
  for (let y = 0; y < rows; y++) raw.set(px.subarray(y * W, y * W + W), y * (W + 1) + 1);
  // zlib stream = header + compressed top + raw rows in stored blocks + Adler-32 of everything
  const parts = [new Uint8Array([0x78, 0xda]), P.top];
  for (let p = 0; p < raw.length; p += 65535) {
    const n = Math.min(65535, raw.length - p), last = p + n >= raw.length;
    parts.push(new Uint8Array([last ? 1 : 0, n & 255, n >> 8, ~n & 255, (~n >> 8) & 255]), raw.subarray(p, p + n));
  }
  let a = OG.topAdler & 0xffff, b = OG.topAdler >>> 16;
  for (let k = 0; k < raw.length; k++) { a = (a + raw[k]) % 65521; b = (b + a) % 65521; }
  const ad = new Uint8Array(4); new DataView(ad.buffer).setUint32(0, ((b << 16) | a) >>> 0); parts.push(ad);
  const idat = concat(parts);
  const ihdr = new Uint8Array(13), v = new DataView(ihdr.buffer);
  v.setUint32(0, W); v.setUint32(4, H); ihdr[8] = 8; ihdr[9] = 3;   // 8-bit, palette
  return concat([new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('PLTE', P.pal), chunk('IDAT', idat), chunk('IEND', new Uint8Array(0))]);
}
const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
function crc32(parts){ let c = 0xffffffff; for (const u of parts) for (let i = 0; i < u.length; i++) c = CRC[(c ^ u[i]) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; }
function chunk(type, data){
  const t = new TextEncoder().encode(type), out = new Uint8Array(12 + data.length), v = new DataView(out.buffer);
  v.setUint32(0, data.length); out.set(t, 4); out.set(data, 8); v.setUint32(8 + data.length, crc32([t, data]));
  return out;
}
function concat(arr){ const n = arr.reduce((t, a) => t + a.length, 0), o = new Uint8Array(n); let p = 0; for (const a of arr) { o.set(a, p); p += a.length; } return o; }

// Preview picture data (made from the "B" design): background as palette indexes, the 10 digits for each
// of the 4 places as 0–15 coverage masks, and a lookup that blends the digit colour over any background colour.
const OG = {"meta":{"W":800,"H":420,"y0":309,"y1":377,"slots":[[523,569],[581,627],[639,685],[697,743]]},"pal":"","lut":"","base":"","masks":"","top":"","topAdler":3953036996};
